'use strict';
const cottage=EldoriaCottageModel;cottage.ensure(state);
const cottageCSS=document.createElement('link');cottageCSS.rel='stylesheet';cottageCSS.href='city-cottage.css?v=1';document.head.append(cottageCSS);
for(const a of cottage.activities)cityLife.P['cottage_'+a.id]={...a,prompt:a.text};
const cottageRoom=id=>cottage.rooms.find(r=>r.id===id);
const cottageOwn=id=>['home','legacyRoom'].includes(id)||!!cottageRoom(id);
const cottageConnections={home:['cottageSitting','cottageKitchen','cottageDen','cottageBedroom'],cottageKitchen:['home','cottageSitting','cottageBasement','cottagePorch'],cottageBath:['cottageBedroom','home'],cottageSitting:['home','cottageKitchen','cottageDen','cottagePorch'],cottageDen:['home','cottageSitting'],cottageBasement:['cottageKitchen','home'],cottageBedroom:['home','cottageBath'],cottagePorch:['cottageKitchen','cottageSitting','cottageYard'],cottageYard:['cottagePorch','home'],legacyRoom:['home','cottageSitting']};
function cottageVisit(id){$('modal').close();if(scene!=='home')changeScene('home');cityEnter(id)}
function cottageDirectory(){modal('Your complete Willowwood cottage','<p>Your cottage now has separate furnished rooms, a covered back porch, and a backyard with tulips and raised vegetable beds. Choose a room to walk into it.</p><div id="cottageFloorplan" class="cottage-floorplan"></div>');for(const [id,name]of [['home','Cottage entrance & belongings'],...cottage.rooms.map(r=>[r.id,r.name]),['legacyRoom','Your Legacy Room']]){const b=document.createElement('button');b.textContent=name;b.dataset.cottageRoom=id;b.onclick=()=>cottageVisit(id);$('cottageFloorplan').append(b)}action('Walk to the neighborhood lane',()=>{$('modal').close();neighborhoodLane()})}
const cottageButton=document.createElement('button');cottageButton.id='cottageRooms';cottageButton.textContent='My cottage rooms';cottageButton.onclick=cottageDirectory;lifeBar.append(cottageButton);
const cottageDescriptionsBefore=comfortPlaceDescription;comfortPlaceDescription=function(id){return cottageRoom(id)?.text||cottageDescriptionsBefore(id)};
const cottageImageBefore=comfortRoomImage;comfortRoomImage=function(id){const room=cottageRoom(id);return room?room.image+(room.outside&&window.ELDORIA_SKY?.phase==='night'?'-night':''):cottageImageBefore(id)};
function cottageRoomMenu(id=cityInside){const room=cottageRoom(id);if(!room||cityInside!==id||scene!=='home')return;modal(room.name,'<p>'+lifeEsc(room.text)+'</p><p id="cottageFeedback" role="status"></p>');lifePhoto(id);for(const a of cottage.activities.filter(a=>a.room===id))action(a.title,()=>cottageActivity(a.id));if(id==='cottageYard')action('Plant, water & harvest my beds',cottageBeds);if(id==='cottageDen')action('Write in my saved cottage journal',cottageJournal);if(['cottageKitchen','cottageSitting','cottagePorch'].includes(id))action('My pantry · eat or share',cottagePantry);if(id==='cottageSitting')action('Read a fireside story',()=>comfortReadStory(0));if(id==='cottageBedroom')action('Choose my clothing & profession',professions);action('Explore this room',()=>{$('modal').close();cityDraw()});action('Walk to another cottage room',cottageDirectory)}
function cottageActivity(id){const a=cottage.activities.find(a=>a.id===id);if(!a)return;const reason=cottage.available(state,a,lifeWhere(),atmosphere.conditions(state));if(reason){modal(a.title,'<p>'+lifeEsc(reason)+'</p>');if(a.cost)action(a.cost==='herbal tea'?'Go to my kitchen':'Go to my vegetable beds',()=>cottageVisit(a.cost==='herbal tea'?'cottageKitchen':'cottageYard'));action('Return to this location',()=>{$('modal').close();cityDraw()});return}lifePuzzle('cottage_'+id,a.title,answer=>{const r=cottage.finish(state,id,answer,lifeWhere(),atmosphere.conditions(state));r.cottage=true;return r})}
const cottageLifeResultBefore=lifeResult;lifeResult=function(r,again){if(!r.cottage||!r.ok)return cottageLifeResultBefore(r,again);lifeCommit();modal(r.title,'<p>'+lifeEsc(r.detail||'Your progress is saved.')+'</p>'+(r.coins?'<p>You earned '+r.coins+' mooncoins. Activity rewards refresh after real midnight.</p>':''));action('Enjoy this location',()=>{$('modal').close();cityDraw()});if(cottageRoom(cityInside))action('More activities in this room',()=>cottageRoomMenu());else action('More local activities',cottageLocal);return true};
function cottageShow(r,again){if(r.ok)lifeCommit();modal(r.ok?r.title:'Your cottage activity','<p>'+lifeEsc(r.detail||r.reason)+'</p>');action('Back to my activity',again);action('Enjoy this location',()=>{$('modal').close();cityDraw()})}
let cottageBedTimer=null;
function cottageBedLabels(){if(!$('cottageBedStatus'))return;const q=cottage.ensure(state);$('cottageBedStatus').textContent=['tulips','vegetables'].map(kind=>{const p=q.patches[kind];return atCap(kind)+': '+(!p?'ready to plant':Date.now()>=p.readyAt?'ready to harvest':Math.ceil((p.readyAt-Date.now())/1000)+' seconds to grow')}).join(' · ')}
function cottageBeds(){if(scene!=='home'||cityInside!=='cottageYard')return;modal('Your tulips & kitchen garden','<p>Your established tulip border stays beautiful. Grow extra tulips for bouquets and vegetables for preserving. Each bed gives one harvest per real calendar day.</p><p id="cottageBedStatus" role="status"></p>');for(const kind of ['tulips','vegetables']){action('Plant & water '+kind,()=>cottageShow(cottage.plant(state,kind,lifeWhere(),atmosphere.conditions(state)),cottageBeds));action('Harvest '+kind,()=>cottageShow(cottage.harvest(state,kind,lifeWhere(),atmosphere.conditions(state)),cottageBeds))}action('Back to my garden activities',()=>cottageRoomMenu());cottageBedLabels();clearInterval(cottageBedTimer);cottageBedTimer=setInterval(cottageBedLabels,1000)}
$('modal').addEventListener('close',()=>clearInterval(cottageBedTimer));
function cottagePantry(){if(scene!=='home'||!['cottageKitchen','cottageSitting','cottagePorch'].includes(cityInside))return;const bag=cottage.ensure(state).bag;modal('Your cottage pantry','<p>Meals and tea made in your kitchen, and jars prepared in your basement, stay here until you use them. Sharing a serving warms your friendship with Fern.</p><div id="cottagePantryList"></div>');const food=['garden soup','cottage loaf','herbal tea','garden preserves'];for(const item of food){const p=document.createElement('p');p.textContent=atCap(item)+' · '+(bag[item]||0)+' servings';$('cottagePantryList').append(p);if(bag[item]>0){action('Enjoy '+item,()=>cottageShow(cottage.serve(state,item,false,lifeWhere()),cottagePantry));action('Share '+item+' with Fern',()=>cottageShow(cottage.serve(state,item,true,lifeWhere()),cottagePantry))}}const p=document.createElement('p');p.textContent='Garden vegetables for preserving: '+(bag['garden vegetables']||0);$('cottagePantryList').append(p);action('Back to this room',()=>cottageRoomMenu())}
function cottageJournal(){if(scene!=='home'||cityInside!=='cottageDen')return;modal('My cottage journal','<p>Keep your goals, recipes, memories and next projects here. Your words stay in your game save and backups.</p><label for="cottageJournalText">My notes</label><textarea id="cottageJournalText" maxlength="2000" rows="8"></textarea><p id="cottageJournalStatus" role="status"></p>');$('cottageJournalText').value=cottage.ensure(state).journal;action('Save my journal',()=>{if(!cottage.write(state,$('cottageJournalText').value,lifeWhere()))return;persist();$('cottageJournalStatus').textContent='Your journal is saved.'});action('Back to my den',()=>cottageRoomMenu('cottageDen'))}
function cottageLocal(){modal(cityShort[scene]+' · more to do','<p>Try a local activity, build a keepsake collection, and return another day for a fresh reward.</p>');for(const a of cottage.activities.filter(a=>a.room===null&&a.district===scene)){action(a.title,()=>{if(cityInside)cityLeave();cottageActivity(a.id)})}action('Adventures, jobs & quests',()=>lifeBoard());action('Back to exploring',()=>{$('modal').close();cityDraw()})}
const cottageUseBefore=cityUse;cityUse=function(kind){if(cottageRoom(kind)&&cityInside===kind){cottageRoomMenu(kind);return}cottageUseBefore(kind)};
const cottageWorkBefore=cityWorkLabel;cityWorkLabel=function(id){return cottageRoom(id)?'Use '+cottageRoom(id).name.toLowerCase():cottageWorkBefore(id)};
const cottageActionsBefore=cityBuildActions;cityBuildActions=function(){cottageActionsBefore();const r=cottageRoom(cityInside);if(scene==='home'&&r){$('comfortPlaces').replaceChildren();$('comfortPlacesTitle').textContent='Make yourself at home · '+r.name;for(const a of cottage.activities.filter(a=>a.room===r.id))cityCard(a.title,a.text,'Begin this activity',()=>cottageActivity(a.id),'✦');if(r.id==='cottageYard')cityCard('A garden that grows','Plant and water cutting tulips or vegetables. Return after one real minute to harvest.','Open my growing beds',cottageBeds,'❀');if(r.id==='cottageDen')cityCard('Your own words','Keep goals, recipes and memories in your saved journal.','Write in my journal',cottageJournal,'▤');if(['cottageKitchen','cottageSitting','cottagePorch'].includes(r.id))cityCard('Your homemade pantry','Enjoy a serving, or share it with Fern.','Open my pantry',cottagePantry,'♧');if(r.id==='cottageSitting')cityCard('A story by the fire','Settle into your chair with the family’s story.','Read by the fire',()=>comfortReadStory(0),'▤');for(const id of cottageConnections[r.id])cityCard(cityRoomNames[id],cottageRoom(id)?.text||'Return through your cottage.','Walk to this room',()=>cottageVisit(id),'⌂',id);cityCard('Every room in your cottage','Choose any room from your home’s directory.','Open my cottage rooms',cottageDirectory,'⌂')}else if(scene==='home'&&['home','legacyRoom'].includes(cityInside)){const card=cityCard('Your cottage has room to live','Kitchen, bathroom, sitting room, den, bedroom, basement, back porch, and your tulip backyard.','Explore all my cottage rooms',cottageDirectory,'⌂');$('comfortPlaces').prepend(card)}if(!cityInside)cityCard('More to do in '+cityShort[scene],'A local project with a saved keepsake and a fresh reward each real day.','Open local activities',cottageLocal,'✦')};
const cottageHotspotsBefore=cityBuildHotspots;cityBuildHotspots=function(){if(scene==='home'&&cottageRoom(cityInside)){$('cityHotspots').replaceChildren();cityTarget('Activities in this room',49,43,()=>cottageRoomMenu(),'work');const links=cottageConnections[cityInside];cityTarget('Door · '+cityRoomNames[links[0]],16,65,()=>cottageVisit(links[0]),'exit',links[0]);const next=links[links.length-1];cityTarget('Door · '+cityRoomNames[next],81,35,()=>cottageVisit(next),'door',next);return}cottageHotspotsBefore();if(scene==='home'&&cityInside==='home')cityTarget('Explore my cottage rooms',52,28,cottageDirectory,'door');};
const cottageTrailBefore=cityBuildRoomTrail;cityBuildRoomTrail=function(){cottageTrailBefore();if(scene!=='home'||!cottageOwn(cityInside))return;const trail=$('cityRoomTrail');trail.replaceChildren();const directory=document.createElement('button');directory.textContent='⌂ All my cottage rooms';directory.onclick=cottageDirectory;trail.append(directory);for(const id of [cityInside,...(cottageConnections[cityInside]||[])]){const b=document.createElement('button');b.textContent=cityRoomNames[id];b.dataset.cottageRoute=id;b.classList.toggle('selected',id===cityInside);b.onclick=()=>cottageVisit(id);trail.append(b)}const lane=document.createElement('button');lane.textContent='Neighborhood lane';lane.dataset.neighborhoodRoute='willowLane';lane.onclick=neighborhoodLane;trail.append(lane)};
const cottagePeopleBefore=cityBuildPeople;cityBuildPeople=function(){cottagePeopleBefore();if(scene==='home'&&cottageRoom(cityInside)){$('cityPeople').replaceChildren();const b=document.createElement('button');b.className='city-person';b.textContent='Invite a friend to your sitting room';b.onclick=()=>cottageVisit('cottageSitting');$('cityPeople').append(b)}};
const cottageDrawBefore=cityDraw;cityDraw=function(){cottageDrawBefore();$('cottageRoomProgress')?.remove();if(scene!=='home'||!cottageRoom(cityInside))return;const r=cottageRoom(cityInside),q=cottage.ensure(state);$('area').textContent='YOUR WILLOWWOOD COTTAGE · '+(r.outside?'OUT IN THE GARDEN':'A ROOM OF YOUR OWN');$('subtitle').textContent=r.text;$('hint').textContent='Use this room’s activities or walk through a connected doorway. All my cottage rooms opens your full home.';const done=cottage.activities.filter(a=>a.room===r.id&&((a.project&&q.projects[a.project])||(a.comfort&&q.comfort[a.comfort])||(a.keepsake&&state.cityLife.collection.includes(a.keepsake))));if(done.length){const p=document.createElement('p');p.id='cottageRoomProgress';p.textContent='Your life in this room: '+done.map(a=>a.project||a.comfort||a.keepsake).join(' · ');$('cityRoomTrail').after(p)}};comfortDraw=cityDraw;
window.ELDORIA_COTTAGE={version:1,openRooms:cottageDirectory,visit:cottageVisit,openLocal:cottageLocal};cityDraw();persist();
